-- # Lernfeld 5: Cyberphysische Systeme > ## Datengrundlagen > - Daten vs. Informationen

INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Können Daten ohne jegliche Verarbeitung als Informationen gelten, wenn sie zufällig interpretierbar sind?', 2, '[{"text": "Nein", "correct": true, "because": "Verarbeitung ist zwingend für Bedeutung"}, {"text": "Ja", "correct": false, "because": "Zufällige Interpretation ist keine Verarbeitung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Informationen stets das Ergebnis einer bewussten Datenanalyse durch einen Menschen?', 2, '[{"text": "Nein", "correct": true, "because": "Automatisierte Systeme können auch Informationen erzeugen"}, {"text": "Ja", "correct": false, "because": "Maschinenanalyse ist möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Verlieren Daten ihre Eigenschaft als Daten, sobald sie zu Informationen verarbeitet wurden?', 2, '[{"text": "Nein", "correct": true, "because": "Daten bleiben Rohmaterial, auch wenn verarbeitet"}, {"text": "Ja", "correct": false, "because": "Verarbeitung löscht Daten nicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist es möglich, dass Informationen ohne jeglichen Datenursprung existieren?', 2, '[{"text": "Nein", "correct": true, "because": "Informationen basieren immer auf Daten"}, {"text": "Ja", "correct": false, "because": "Daten sind die Grundlage"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann der Kontext von Daten allein ausreichen, um sie ohne weitere Verarbeitung in Informationen umzuwandeln?', 2, '[{"text": "Nein", "correct": true, "because": "Verarbeitung ist essenziell, Kontext allein reicht nicht"}, {"text": "Ja", "correct": false, "because": "Kontext ohne Verarbeitung ist unzureichend"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Element unterscheidet Daten von Informationen primär?', 2, '[{"text": "Verarbeitung und Kontext", "correct": true, "because": "Diese geben Daten Bedeutung"}, {"text": "Speicherort", "correct": false, "because": "Irrelevant für den Unterschied"}, {"text": "Datenmenge", "correct": false, "because": "Quantität ist kein Kriterium"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert mit Daten, wenn sie ohne Analyse in einen Bericht eingefügt werden?', 3, '[{"text": "Sie bleiben Daten", "correct": true, "because": "Ohne Verarbeitung keine Informationen"}, {"text": "Sie werden automatisch Informationen", "correct": false, "because": "Verarbeitung fehlt"}, {"text": "Sie verlieren ihre Relevanz", "correct": false, "because": "Relevanz hängt von Nutzung ab"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Prozess ist entscheidend, um aus einer zufälligen Zeichenfolge wie "X7K9P" eine Information zu machen?', 2, '[{"text": "Interpretation mit Kontext", "correct": true, "because": "Kontext gibt Bedeutung"}, {"text": "Komprimierung der Zeichen", "correct": false, "because": "Ändert nichts an Bedeutung"}, {"text": "Erhöhung der Datenmenge", "correct": false, "because": "Menge ist irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was beschreibt den Übergang von Daten zu Informationen am präzisesten?', 2, '[{"text": "Sinnstiftung durch Verarbeitung", "correct": true, "because": "Verarbeitung erzeugt Bedeutung"}, {"text": "Speicherung in einer Datenbank", "correct": false, "because": "Speicherung verändert nichts"}, {"text": "Übertragung an einen Empfänger", "correct": false, "because": "Übertragung ist sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aussage trifft auf Daten ohne Kontext am ehesten zu?', 2, '[{"text": "Sie sind potenziell nutzlos", "correct": true, "because": "Ohne Kontext fehlt Bedeutung"}, {"text": "Sie sind automatisch falsch", "correct": false, "because": "Falschheit ist kein Kriterium"}, {"text": "Sie werden zu Informationen", "correct": false, "because": "Verarbeitung fehlt"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren sind erforderlich, um Daten in Informationen umzuwandeln?', 4, '[{"text": "Strukturierung", "correct": true, "because": "Macht Daten lesbar"}, {"text": "Kontext", "correct": true, "because": "Gibt Bedeutung"}, {"text": "Interpretation", "correct": true, "because": "Erzeugt Verständnis"}, {"text": "Hardwareleistung", "correct": false, "because": "Technisch, aber nicht inhaltlich relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Beispiele könnten als reine Daten gelten?', 3, '[{"text": "Binärcode: 101010", "correct": true, "because": "Unverarbeitet"}, {"text": "Tabelle mit erklärten Werten", "correct": false, "because": "Schon interpretiert"}, {"text": "Liste von IP-Adressen", "correct": true, "because": "Rohdaten"}, {"text": "Diagramm mit Legende", "correct": false, "because": "Verarbeitet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aussagen über Informationen sind korrekt?', 4, '[{"text": "Sie erfordern Daten als Basis", "correct": true, "because": "Ohne Daten keine Infos"}, {"text": "Sie sind subjektiv interpretierbar", "correct": true, "because": "Hängt vom Empfänger ab"}, {"text": "Sie sind immer eindeutig", "correct": false, "because": "Können mehrdeutig sein"}, {"text": "Sie entstehen durch Verarbeitung", "correct": true, "because": "Verarbeitung ist essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Prozesse könnten Daten irrtümlich als Informationen erscheinen lassen?', 3, '[{"text": "Darstellung in einem Diagramm", "correct": true, "because": "Sieht verarbeitet aus"}, {"text": "Speicherung in einer Datei", "correct": false, "because": "Ändert nichts an Bedeutung"}, {"text": "Zufällige Anordnung", "correct": true, "because": "Kann Sinn vortäuschen"}, {"text": "Komprimierung", "correct": false, "because": "Technisch, nicht semantisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was charakterisiert Daten im Vergleich zu Informationen?', 3, '[{"text": "Fehlende Interpretation", "correct": true, "because": "Rohzustand"}, {"text": "Potenzial für Bedeutung", "correct": true, "because": "Durch Verarbeitung nutzbar"}, {"text": "Immer visuell dargestellt", "correct": false, "because": "Form ist egal"}, {"text": "Abhängigkeit von Kontext", "correct": false, "because": "Kontext fehlt oft"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Daten können ohne Verarbeitung Bedeutung haben, wenn sie strukturiert sind. b) Informationen sind unabhängig vom Empfänger immer gleich.', 3, '[{"text": "Beides falsch", "correct": true, "because": "Verarbeitung nötig, Empfänger beeinflusst"}, {"text": "Nur a) stimmt", "correct": false, "because": "Struktur allein reicht nicht"}, {"text": "Nur b) stimmt", "correct": false, "because": "Empfängerabhängig"}, {"text": "Beides stimmt", "correct": false, "because": "Beides falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Informationen entstehen nur durch menschliche Interpretation. b) Daten sind per Definition kontextlos.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Maschinen können Infos erzeugen, Daten ohne Kontext"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Der Übergang von Daten zu Informationen erfordert zwingend eine Software. b) Daten können mehrdeutig sein.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Software nicht zwingend, Daten mehrdeutig möglich"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Informationen sind stets das Endergebnis einer Datenanalyse. b) Daten verlieren ihren Status, sobald sie interpretiert werden.', 3, '[{"text": "Beides falsch", "correct": true, "because": "Infos können Zwischenschritt sein, Daten bleiben"}, {"text": "Nur a) stimmt", "correct": false, "because": "Infos nicht immer Endergebnis"}, {"text": "Nur b) stimmt", "correct": false, "because": "Daten bleiben Daten"}, {"text": "Beides stimmt", "correct": false, "because": "Beides falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Kontext kann Daten ohne Verarbeitung nutzbar machen. b) Informationen sind objektiv und kontextunabhängig.', 3, '[{"text": "Beides falsch", "correct": true, "because": "Verarbeitung nötig, Infos kontextabhängig"}, {"text": "Nur a) stimmt", "correct": false, "because": "Kontext allein reicht nicht"}, {"text": "Nur b) stimmt", "correct": false, "because": "Infos sind subjektiv"}, {"text": "Beides stimmt", "correct": false, "because": "Beides falsch"}]');

